# Definitions only. The root performs one normal authenticated GET after restoration.
function ConvertTo-Phase08OutageWarning($Value){
 if($Value -isnot [Collections.IDictionary] -or $Value.Count -ne 4 -or @(@('items','history','historyLimits','automaticBackfill')|Where-Object {-not $Value.Contains($_)}).Count -ne 0 -or $Value.automaticBackfill -isnot [bool] -or $Value.automaticBackfill -or $Value.items -isnot [array] -or $Value.items.Count -gt 3 -or $Value.history -isnot [array] -or $Value.history.Count -lt 2 -or $Value.history.Count -gt 3){throw 'OUTAGE_WARNING_REJECTED'}
 $missing=@('2026-10-08','2026-10-09','2026-10-10','2026-10-11','2026-10-12','2026-10-13','2026-10-14');$keys=@('phase08-cafe24','phase08-google','phase08-meta');$seen=@{};$meta=0
 foreach($item in $Value.items){
  if($item -isnot [Collections.IDictionary] -or $item.Count -ne 8 -or @(@('scheduleKey','scheduledFor','fromDate','toDate','id','status','warningCode','missingDates')|Where-Object {-not $item.Contains($_)}).Count -ne 0 -or $item.scheduleKey -isnot [string] -or $item.scheduleKey -cnotin $keys -or $seen.ContainsKey($item.scheduleKey) -or ($null -ne $item.id -and ($item.id -isnot [string] -or $item.id -cnotmatch '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$')) -or $item.missingDates -isnot [array] -or $item.missingDates.Count -lt 1 -or $item.missingDates.Count -gt 7 -or @($item.missingDates|Where-Object {$_ -isnot [string] -or $_ -cnotin $missing}).Count -ne 0 -or @($item.missingDates|Select-Object -Unique).Count -ne $item.missingDates.Count -or $item.toDate -cne '2026-10-14'){throw 'OUTAGE_WARNING_REJECTED'}
  $seen[$item.scheduleKey]=$true
  if($item.scheduleKey -ceq 'phase08-meta'){
   if($item.scheduledFor -cne '2026-10-15T06:00:00.000Z' -or $item.fromDate -cne '2026-10-08' -or $item.status -cne 'EXPIRED' -or $item.warningCode -cne 'MISSING_SCHEDULE' -or ($item.missingDates -join '|') -cne ($missing -join '|') -or $null -ne $item.id){throw 'OUTAGE_WARNING_REJECTED'};$meta++
  }else{
   $cafe=$item.scheduleKey -ceq 'phase08-cafe24';$expected=if($cafe){'2026-10-15T06:40:00.000Z'}else{'2026-10-14T17:01:00.000Z'}
   if($item.scheduledFor -cne $expected -or $item.fromDate -cne $(if($cafe){'2026-10-14'}else{'2026-10-08'}) -or $item.status -isnot [string] -or $item.status -cnotin @('NOT_STARTED','QUEUED','RUNNING','PARTIAL','FAILED','ACTION_REQUIRED','EXPIRED') -or $item.warningCode -isnot [string] -or $item.warningCode -cnotin @('MISSING_SCHEDULE','SCHEDULE_INCOMPLETE') -or ($cafe -and ($item.missingDates -join '|') -cne '2026-10-14')){throw 'OUTAGE_WARNING_REJECTED'}
  }
 }
 if($meta -ne 1){throw 'OUTAGE_WARNING_REJECTED'};$seen=@{}
 foreach($row in $Value.history){if($row -isnot [Collections.IDictionary] -or $row.Count -ne 4 -or @(@('scheduleKey','trackingFromDate','truncatedEarlierWindows','warningCode')|Where-Object {-not $row.Contains($_)}).Count -ne 0 -or $row.scheduleKey -isnot [string] -or $row.scheduleKey -cnotin $keys -or $seen.ContainsKey($row.scheduleKey) -or $row.truncatedEarlierWindows -isnot [bool] -or $row.truncatedEarlierWindows -or $null -ne $row.warningCode -or $row.trackingFromDate -cne $(if($row.scheduleKey -ceq 'phase08-cafe24'){'2026-10-14'}else{'2026-10-08'})){throw 'OUTAGE_WARNING_REJECTED'};$seen[$row.scheduleKey]=$true}
 if(-not $seen.ContainsKey('phase08-meta') -or -not $seen.ContainsKey('phase08-google') -or $Value.historyLimits -isnot [Collections.IDictionary] -or $Value.historyLimits.Count -ne 2){throw 'OUTAGE_WARNING_REJECTED'}
 foreach($pair in @(@('cafe24Occurrences',31),@('adsOccurrences',5))){$name=$pair[0];if(-not $Value.historyLimits.Contains($name) -or ($Value.historyLimits[$name] -isnot [int] -and $Value.historyLimits[$name] -isnot [long]) -or $Value.historyLimits[$name] -ne $pair[1]){throw 'OUTAGE_WARNING_REJECTED'}}
 return @{state='PHASE08_OUTAGE_WARNING_VERIFIED';scheduleKey='phase08-meta';scheduledFor='2026-10-15T06:00:00.000Z';fromDate='2026-10-08';toDate='2026-10-14';missingDates=$missing;missingDateCount=7;warningCode='MISSING_SCHEDULE';warningStatus='EXPIRED';otherWarningCount=$Value.items.Count-1;historyCount=$Value.history.Count;automaticBackfill=$false;providerRequests=0;databaseWrites=0;rawValuesReturned=0}
}
